// Target UID to switch to (e.g., non-root user)
const uid_t TARGET_UID = 1000;

// Attempt to drop privileges
if (setuid(TARGET_UID) == -1) {
    // EPERM: Caller lacks CAP_SETUID capability
    // EAGAIN: Temporary resource allocation failure
    // Log failure via perror() or similar
    // ... handle error
}

// Privileges successfully dropped (Effective UID is now TARGET_UID)
// If privileged, Real and Saved UIDs are also set to TARGET_UID
// Cannot regain root privileges after this call unless Saved UID permits
// (i.e., if setuid() only dropped effective UID, not all three).
